import{_ as r,a0 as l,w as d,s as u,ao as p,I as o,x as i,a1 as t,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"Pidgin：Skype for Business 的开源替代品 | LCTT x X-CMD","titleTemplate":false,"description":"Pidgin：Skype for Business 的开源替代品 | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Pidgin：Skype for Business 的开源替代品 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Pidgin：Skype for Business 的开源替代品 | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180426 Get started with Pidgin- An open source replacement for Skype for Business","title":"Pidgin：Skype for Business 的开源替代品","tag":"201806","desc":""},"relativePath":"201806/20180426 Get started with Pidgin- An open source replacement for Skype for Business.md","filePath":"[post].md"}'),a={name:"201806/20180426 Get started with Pidgin- An open source replacement for Skype for Business.md"};function f(g,e,m,P,k,y){const s=l("Link");return d(),u("div",null,[e[29]||(e[29]=p('<h1 id="pidgin-skype-for-business-的开源替代品" tabindex="-1">Pidgin：Skype for Business 的开源替代品 <a class="header-anchor" href="#pidgin-skype-for-business-的开源替代品" aria-label="Permalink to “Pidgin：Skype for Business 的开源替代品”">​</a></h1><blockquote><p>用可以和 Office 365 协同工作的开源软件换下你的专有化的沟通软件。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/meeting-team-listen-communicate.png?itok=KEBP6vZ_" alt=""></p><p>技术正处在一个有趣的十字路口，Linux 统治服务器领域，但微软统治企业桌面。 Office 365、Skype for Business、Microsoft Teams、OneDrive、Outlook ......等等，这些是支配企业工作空间的是微软软件和服务。</p><p>如果你可以使用自由和开源程序替换该专有软件，并使其与你别无选择，但只能使用的 Office 365 的后端一起工作？是的，因为这正是我们要用 Pidgin 做的，它是 Skype 的开源替代品。</p><h3 id="安装-pidgin-和-sipe" tabindex="-1">安装 Pidgin 和 SIPE <a class="header-anchor" href="#安装-pidgin-和-sipe" aria-label="Permalink to “安装 Pidgin 和 SIPE”">​</a></h3>',6)),o("p",null,[e[2]||(e[2]=i("微软的 Office Communicator 变成了 Microsoft Lync，它成为我们今天所知的 Skype for Business。现在有针对 Linux 的",-1)),t(s,{href:"https://tel.red/linux.php"},{default:n(()=>[...e[0]||(e[0]=[i("付费软件",-1)])]),_:1}),e[3]||(e[3]=i("提供了与 Skype for Business 相同的功能，但 ",-1)),t(s,{href:"https://pidgin.im/"},{default:n(()=>[...e[1]||(e[1]=[i("Pidgin",-1)])]),_:1}),e[4]||(e[4]=i(" 是 GNU GPL 授权的、完全自由开源的选择。",-1))]),e[30]||(e[30]=o("p",null,"Pidgin 可以在几乎每个 Linux 发行版的仓库中找到，因此，使用它不应该是一个问题。唯一不能在 Pidgin 中使用的 Skype 功能是屏幕共享，并且文件共享可能会失败，但有办法解决这个问题。",-1)),o("p",null,[e[6]||(e[6]=i("你还需要一个 ",-1)),t(s,{href:"http://sipe.sourceforge.net/"},{default:n(()=>[...e[5]||(e[5]=[i("SIPE",-1)])]),_:1}),e[7]||(e[7]=i(" 插件，因为它是使 Pidgin 成为 Skype for Business 替代品的秘密武器的一部分。请注意，",-1)),e[8]||(e[8]=o("code",null,"sipe",-1)),e[9]||(e[9]=i(" 库在不同的发行版中有不同的名称。例如，库在 System76 的 Pop_OS! 中是 ",-1)),e[10]||(e[10]=o("code",null,"pidgin-sipe",-1)),e[11]||(e[11]=i("，而在 Solus 3 仓库中是 ",-1)),e[12]||(e[12]=o("code",null,"sipe",-1)),e[13]||(e[13]=i("。",-1))]),e[31]||(e[31]=p('<p>满足了先决条件，你可以开始配置 Pidgin。</p><h3 id="配置-pidgin" tabindex="-1">配置 Pidgin <a class="header-anchor" href="#配置-pidgin" aria-label="Permalink to “配置 Pidgin”">​</a></h3><p>首次启动 Pidgin 时，点击 “Add” 添加一个新帐户。在基本选项卡（如下截图所示）中，选择 “Protocol” 下拉菜单中的 “Office Communicator”，然后在 “Username” 字段中输入你的“公司电子邮件地址”。</p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/u128651/pidgin_basic_account_screen_final.png?itok=1zoSbZjy" alt=""></p><p>接下来，点击高级选项卡。在 “Server[:Port]” 字段中输入 “sipdir.online.lync.com:443”，在 “User Agent” 中输入 “UCCAPI/16.0.6965.5308 OC/16.0.6965.2117”。</p><p>你的高级选项卡现在应该如下所示：</p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/u128651/pidgin_advanced_account_screen.png?itok=Z6loRfGi" alt=""></p><p>你不需要对“Proxy”选项卡或“Voice and Video”选项卡进行任何更改。只要确定，请确保 “Proxy type” 设置为 “Use Global Proxy Settings”，并且在“Voice and Video”选项卡中，“Use silence suppression” 复选框为<strong>取消选中</strong>。</p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/u128651/pidgin_account_proxy_screen.png?itok=iDgszWy0" alt=""></p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/u128651/pidgin_voiceandvideo_screen.png?itok=klkbt5hr" alt=""></p><p>完成这些配置后，点击 “Add”，系统会提示你输入电子邮件帐户的密码。</p><h3 id="添加联系人" tabindex="-1">添加联系人 <a class="header-anchor" href="#添加联系人" aria-label="Permalink to “添加联系人”">​</a></h3><p>要将联系人添加到好友列表，请点击<strong>好友窗口</strong>中的 “Manage Accounts”。将鼠标悬停在你的帐户上，然后选择 “Contact Search” 查找你的同事。如果您在使用姓氏和名字进行搜索时遇到任何问题，请尝试使用你同事的完整电子邮件地址进行搜索，你就会找到正确的人。</p><p>你现在已经开始使用 Skype for Business 替代产品，该产品可为你提供 98％ 的功能，从你的桌面上消除专有软件。</p><hr>',15)),o("p",null,[e[15]||(e[15]=i("via: ",-1)),t(s,{href:"https://opensource.com/article/18/4/pidgin-open-source-replacement-skype-business"},{default:n(()=>[...e[14]||(e[14]=[i("https://opensource.com/article/18/4/pidgin-open-source-replacement-skype-business",-1)])]),_:1})]),o("p",null,[e[20]||(e[20]=i("作者：",-1)),t(s,{href:"https://opensource.com/users/shickmo"},{default:n(()=>[...e[16]||(e[16]=[i("Ray Shimko",-1)])]),_:1}),e[21]||(e[21]=i(" 选题：",-1)),t(s,{href:"https://github.com/lujun9972"},{default:n(()=>[...e[17]||(e[17]=[i("lujun9972",-1)])]),_:1}),e[22]||(e[22]=i(" 译者：",-1)),t(s,{href:"https://github.com/geekpi"},{default:n(()=>[...e[18]||(e[18]=[i("geekpi",-1)])]),_:1}),e[23]||(e[23]=i(" 校对：",-1)),t(s,{href:"https://github.com/wxy"},{default:n(()=>[...e[19]||(e[19]=[i("wxy",-1)])]),_:1})]),o("p",null,[e[26]||(e[26]=i("本文由 ",-1)),t(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[24]||(e[24]=[i("LCTT",-1)])]),_:1}),e[27]||(e[27]=i(" 原创编译，",-1)),t(s,{href:"https://linux.cn/"},{default:n(()=>[...e[25]||(e[25]=[i("Linux中国",-1)])]),_:1}),e[28]||(e[28]=i(" 荣誉推出",-1))])])}const x=r(a,[["render",f]]);export{b as __pageData,x as default};
